def max_product_after_cut(n):
    if n <= 1:
        return 0
    if n == 2:
        return 1
    if n == 3:
        return 2

    # For n >= 4, the best strategy is to break n into as many 3s as possible,
    # with special handling when the remainder is 1 (use a 4 instead of 3+1).
    q, r = divmod(n, 3)
    if r == 0:
        return 3 ** q
    if r == 1:
        return 3 ** (q - 1) * 4
    return 3 ** q * 2
