def max_product_after_cut(n):
    # Classical result: to maximize the product, split n into as many 3s as
    # possible. When n % 3 == 1, use one 4 (i.e. 2+2) instead of 3+1;
    # when n % 3 == 2, use one 2.
    if n < 2 or n > 1000:
        raise ValueError("n must satisfy 2 <= n <= 1000")
    if n == 2:
        return 1
    if n == 3:
        return 2
    q, r = divmod(n, 3)
    if r == 0:
        return 3 ** q
    if r == 1:
        return 3 ** (q - 1) * 4
    return 3 ** q * 2
```

