def min_assignment_cost(cost):
    n = len(cost)
    if n == 0:
        return 0
    full = (1 << n) - 1
    INF = float('inf')
    # dp[mask] = min cost to fill first popcount(mask) rows using exactly the columns in mask
    dp = [INF] * (1 << n)
    dp[0] = 0
    for mask in range(1 << n):
        if dp[mask] == INF:
            continue
        r = bin(mask).count('1')  # next row to assign
        if r >= n:
            continue
        for c in range(n):
            if not (mask >> c) & 1:
                new = mask | (1 << c)
                val = dp[mask] + cost[r][c]
                if val < dp[new]:
                    dp[new] = val
    return dp[full]
```

