def min_assignment_cost(cost):
    n = len(cost)
    if n == 0:
        return 0

    # Backtracking over rows with memoization on the set of used columns.
    # For n <= 8, each column is representable by a bit in an 8-bit mask.
    memo = {}

    def solve(row, used_mask):
        if row == n:
            return 0
        key = (row, used_mask)
        if key in memo:
            return memo[key]
        best = None
        for col in range(n):
            if not (used_mask >> col) & 1:
                candidate = cost[row][col] + solve(row + 1, used_mask | (1 << col))
                if best is None or candidate < best:
                    best = candidate
        memo[key] = best
        return best

    return solve(0, 0)
