def minimize_largest_block_sum(nums, k):
    n = len(nums)
    if k == n:
        return max(nums)

    def blocks_needed(limit):
        count = 1
        current = 0
        for x in nums:
            if current + x > limit:
                count += 1
                current = x
            else:
                current += x
        return count

    lo, hi = max(nums), sum(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if blocks_needed(mid) <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
