def minimize_largest_block_sum(nums, k):
    n = len(nums)
    if k >= n:
        return max(nums)

    prefix = [0] * (n + 1)
    for i, v in enumerate(nums):
        prefix[i + 1] = prefix[i] + v

    def blocks_needed(limit):
        count = 1
        running = 0
        for v in nums:
            if running + v > limit:
                count += 1
                running = v
            else:
                running += v
        return count

    lo = max(nums)
    hi = sum(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if blocks_needed(mid) <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
