def count_n_queens(n):
    """Count the number of solutions to the n-queens problem for 0 <= n <= 10.

    Two queens attack each other if they share a row, column, or diagonal.
    Each solution is counted as a distinct arrangement (symmetries are not
    factored out). The empty 0x0 board has exactly one arrangement.
    """
    if n == 0:
        return 1

    def solve(row, cols, diag1, diag2):
        if row == n:
            return 1
        count = 0
        for col in range(n):
            d1 = row - col + n - 1  # index into "\" diagonal occupancy
            d2 = row + col          # index into "/" diagonal occupancy
            if cols & (1 << col):
                continue
            if diag1 & (1 << d1):
                continue
            if diag2 & (1 << d2):
                continue
            count += solve(row + 1, cols | (1 << col),
                           diag1 | (1 << d1), diag2 | (1 << d2))
        return count

    return solve(0, 0, 0, 0)
```

