from collections import deque

def grid_wall_escape(grid, k):
    rows = len(grid)
    cols = len(grid[0])
    start = (0, 0)
    finish = (rows - 1, cols - 1)

    # state: (row, col, walls_entered_so_far)
    start_state = (0, 0, 0)
    if start == finish:
        return 0

    dist = {start_state: 0}
    queue = deque([start_state])

    while queue:
        r, c, w = queue.popleft()
        d = dist[(r, c, w)]

        if (r, c) == finish:
            return d

        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                nw = w + (1 if grid[nr][nc] == '#' else 0)
                if nw <= k:
                    state = (nr, nc, nw)
                    if state not in dist:
                        dist[state] = d + 1
                        queue.append(state)

    return -1
