from collections import deque

def grid_wall_escape(grid, k):
    rows, cols = len(grid), len(grid[0])
    start, goal = (0, 0), (rows - 1, cols - 1)
    if start == goal:
        return 0
    # State: (row, col, walls_entered_so_far).
    # dist[r][c][w] = fewest steps to reach cell (r,c) having entered exactly w wall cells.
    INF = float('inf')
    dist = [[[INF] * (k + 1) for _ in range(cols)] for _ in range(rows)]
    start_walls = 1 if grid[0][0] == '#' else 0
    # Start cell is guaranteed open, so start_walls is 0; still handle generically.
    if start_walls > k:
        return -1
    dist[0][0][start_walls] = 0
    dq = deque([(0, 0, start_walls)])
    while dq:
        r, c, w = dq.popleft()
        d = dist[r][c][w]
        if (r, c) == goal:
            return d
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '#':
                    nw = w + 1
                    if nw <= k and dist[nr][nc][nw] > d + 1:
                        dist[nr][nc][nw] = d + 1
                        dq.append((nr, nc, nw))
                else:
                    if dist[nr][nc][w] > d + 1:
                        dist[nr][nc][w] = d + 1
                        dq.append((nr, nc, w))
    return -1
