def count_domino_tilings(rows, cols):
    if rows * cols > 16:
        raise ValueError("rows * cols must be at most 16")
    if rows < 0 or cols < 0:
        raise ValueError("dimensions must be nonnegative")
    if rows == 0 or cols == 0:
        return 1

    # Work with the smaller dimension as the "width" scanned column by column.
    if rows > cols:
        rows, cols = cols, rows

    # dp[mask] = number of ways to tile the columns processed so far, where
    # `mask` marks which cells of the current column are already filled by
    # horizontal dominoes protruding from the previous column.
    dp = {0: 1}
    for _ in range(cols):
        ndp = {}
        for mask, count in dp.items():
            # Generate all ways to fill the current column given incoming mask.
            def fill(row, mask, carry):
                if row == rows:
                    ndp[carry] = ndp.get(carry, 0) + count
                    return
                if mask & (1 << row):
                    fill(row + 1, mask, carry)
                    return
                # Place a vertical domino covering rows `row` and `row + 1`.
                if row + 1 < rows and not (mask & (1 << (row + 1))):
                    fill(row + 2, mask, carry)
                # Place a horizontal domino: occupies this row now and the
                # same row in the next column (recorded in `carry`).
                fill(row + 1, mask, carry | (1 << row))

            fill(0, mask, 0)
    return dp.get(0, 0)

def count_domino_tilings(rows, cols):
    if rows < 0 or cols < 0:
        raise ValueError("dimensions must be nonnegative")
    if rows * cols > 16:
        raise ValueError("rows * cols must be at most 16")
    if rows == 0 or cols == 0:
        return 1

    # Scan column by column; keep `rows` as the smaller dimension so the
    # column bitmask stays small.
    if rows > cols:
        rows, cols = cols, rows

    # dp[mask]: number of tilings of the processed prefix where `mask` marks
    # the cells of the current column already occupied by horizontal
    # dominoes sticking out of the previous column.
    dp = {0: 1}
    for _ in range(cols):
        ndp = {}
        for mask, count in dp.items():
            stack = [(0, mask, 0)]
            while stack:
                row, m, carry = stack.pop()
                if row == rows:
                    ndp[carry] = ndp.get(carry, 0) + count
                    continue
                if m & (1 << row):
                    stack.append((row + 1, m, carry))
                    continue
                # Vertical domino spanning rows `row` and `row + 1`.
                if row + 1 < rows and not (m & (1 << (row + 1))):
                    stack.append((row + 2, m, carry))
                # Horizontal domino extending into the next column.
                stack.append((row + 1, m, carry | (1 << row)))
        dp = ndp

    return dp.get(0, 0)

