def count_domino_tilings(rows, cols):
    if rows * cols == 0:
        return 1
    if (rows * cols) % 2 == 1:
        return 0
    if rows > cols:
        rows, cols = cols, rows

    if cols == 1:
        return 1

    # Precompute reachable masks for transfer matrix over columns.
    # State: mask of cells in current column already filled by horizontal
    # dominoes protruding from the previous column.
    from functools import lru_cache

    width = rows

    # For each mask, compute list of (next_mask) transitions within one column.
    # We do this lazily with memoized DFS over rows within the column.
    @lru_cache(maxsize=None)
    def transitions(mask):
        result = []

        def dfs(pos, cur_mask, out_mask):
            if pos == width:
                result.append(out_mask)
                return
            if cur_mask & (1 << pos):
                dfs(pos + 1, cur_mask, out_mask)
                return
            # place vertical domino (within column)
            if pos + 1 < width and not (cur_mask & (1 << (pos + 1))):
                dfs(pos + 2, cur_mask, out_mask)
            # place horizontal domino (protrudes to next column)
            dfs(pos + 1, cur_mask, out_mask | (1 << pos))

        dfs(0, mask, 0)
        return result

    # DP over columns
    from collections import defaultdict

    dp = defaultdict(int)
    dp[0] = 1
    for _ in range(cols):
        ndp = defaultdict(int)
        for mask, count in dp.items():
            for nxt in transitions(mask):
                ndp[nxt] += count
        dp = ndp

    return dp.get(0, 0)
