def excel_column_title(n):
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("column number must be a positive integer")
    digits = []
    while n > 0:
        n, rem = divmod(n - 1, 26)
        digits.append(chr(ord("A") + rem))
    return "".join(reversed(digits))
