def trap_rain_water(heights):
    n = len(heights)
    if n == 0:
        return 0

    total = 0
    left_max = 0
    right_max = 0
    lo = 0
    hi = n - 1

    while lo < hi:
        if heights[lo] <= heights[hi]:
            if heights[lo] >= left_max:
                left_max = heights[lo]
            else:
                total += left_max - heights[lo]
            lo += 1
        else:
            if heights[hi] >= right_max:
                right_max = heights[hi]
            else:
                total += right_max - heights[hi]
            hi -= 1

    return total
