def word_pattern_bijection(pattern, s):
    """
    Return True iff the words of s follow `pattern` via a bijection.

    Each pattern character must always map to the same word, and no two
    distinct pattern characters may map to the same word. The number of
    words (from s.split()) must equal len(pattern). Matching is
    case-sensitive.
    """
    words = s.split()
    if len(words) != len(pattern):
        return False

    char_to_word = {}
    word_to_char = {}

    for ch, word in zip(pattern, words):
        mapped_word = char_to_word.get(ch)
        mapped_char = word_to_char.get(word)

        if mapped_word is None and mapped_char is None:
            char_to_word[ch] = word
            word_to_char[word] = ch
        elif mapped_word != word or mapped_char != ch:
            return False

    return True

