def word_pattern_bijection(pattern, s):
    """Return True iff the words of s follow pattern via a bijection.

    Words are obtained with s.split(); each pattern character must map to a
    unique word and distinct characters must map to distinct words. Matching
    is case-sensitive.
    """
    words = s.split()
    if len(words) != len(pattern):
        return False
    char_to_word = {}
    word_to_char = {}
    for ch, word in zip(pattern, words):
        if ch in char_to_word:
            if char_to_word[ch] != word:
                return False
        else:
            char_to_word[ch] = word
        if word in word_to_char:
            if word_to_char[word] != ch:
                return False
        else:
            word_to_char[word] = ch
    return True
