def summary_ranges(nums):
    if not nums:
        return []

    ranges = []
    start = nums[0]
    prev = nums[0]

    for x in nums[1:]:
        if x == prev:
            continue  # duplicate, same value
        if x == prev + 1:
            prev = x
        else:
            if prev > start:
                ranges.append(f"{start}->{prev}")
            else:
                ranges.append(str(start))
            start = x
            prev = x

    if prev > start:
        ranges.append(f"{start}->{prev}")
    else:
        ranges.append(str(start))

    return ranges
```

