def summary_ranges(nums):
    if not nums:
        return []
    result = []
    start = prev = nums[0]
    for n in nums[1:]:
        if n == prev + 1:
            prev = n
        elif n == prev:
            continue
        elif n > prev + 1:
            result.append(str(start) if start == prev else f"{start}->{prev}")
            start = prev = n
        else:
            raise ValueError("input must be sorted in non-decreasing order")
    result.append(str(start) if start == prev else f"{start}->{prev}")
    return result
