def knapsack_reconstruct(weights, values, capacity):
    if len(weights) != len(values):
        raise ValueError("weights and values must have the same length")
    if capacity < 0:
        raise ValueError("capacity must be non-negative")
    for w in weights:
        if w < 0:
            raise ValueError("weights must be non-negative")
    for v in values:
        if v < 0:
            raise ValueError("values must be non-negative")

    n = len(weights)
    # dp[c] = best value achievable with capacity c using items considered so far
    dp = [0] * (capacity + 1)

    # keep[i][c] = True if item i is taken at state (i, c)
    keep = [[False] * (capacity + 1) for _ in range(n)]

    for i in range(n):
        wi = weights[i]
        vi = values[i]
        for c in range(capacity, wi - 1, -1):
            candidate = dp[c - wi] + vi
            if candidate > dp[c]:
                dp[c] = candidate
                keep[i][c] = True

    best = dp[capacity]
    indices = []
    c = capacity
    for i in range(n - 1, -1, -1):
        if keep[i][c]:
            indices.append(i)
            c -= weights[i]
    indices.reverse()
    return (best, indices)
