def knapsack_reconstruct(weights, values, capacity):
    if len(weights) != len(values):
        raise ValueError("weights and values must have the same length")
    if capacity < 0:
        raise ValueError("capacity must be non-negative")
    if any(w < 0 for w in weights) or any(v < 0 for v in values):
        raise ValueError("weights and values must be non-negative")

    n = len(weights)

    # dp[c] = max value achievable with total weight <= c
    dp = [0] * (capacity + 1)
    # choice[c] = last item added when dp[c] was last improved, else None
    choice = [None] * (capacity + 1)

    for i in range(n):
        w, v = weights[i], values[i]
        for c in range(capacity, w - 1, -1):
            candidate = dp[c - w] + v
            if candidate > dp[c]:
                dp[c] = candidate
                choice[c] = i

    best = dp[capacity]

    # Reconstruct: walk back through the choice pointers.
    indices = []
    c = capacity
    while c > 0 and choice[c] is not None:
        i = choice[c]
        indices.append(i)
        c -= weights[i]
    indices.reverse()
    indices.sort()

    return (best, indices)

def knapsack_reconstruct(weights, values, capacity):
    if len(weights) != len(values):
        raise ValueError("weights and values must have the same length")
    if capacity < 0:
        raise ValueError("capacity must be non-negative")
    if any(w < 0 for w in weights) or any(v < 0 for v in values):
        raise ValueError("weights and values must be non-negative")

    n = len(weights)

    # take[i][c] = True if item i is part of an optimal solution for
    #              the subproblem (items 0..i, capacity c).
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]

    for i in range(n):
        w, v = weights[i], values[i]
        prev = dp[i]
        curr = dp[i + 1]
        for c in range(capacity + 1):
            best_here = prev[c]
            if w <= c:
                cand = prev[c - w] + v
                if cand > best_here:
                    best_here = cand
            curr[c] = best_here

    best = dp[n][capacity]

    # Backtrack through the DP table.
    indices = []
    c = capacity
    for i in range(n - 1, -1, -1):
        if dp[i + 1][c] != dp[i][c]:
            # Item i was taken in the optimal solution for this subproblem.
            indices.append(i)
            c -= weights[i]

    indices.reverse()
    return (best, indices)

