    dp = [0] * (capacity + 1)
    # choice[c] = 1 if item i was added to reach dp[c] at step i, else 0
    choice = [[0] * (capacity + 1) for _ in range(n)]

    for i in range(n):
        wi = weights[i]
        vi = values[i]
        for c in range(capacity, wi - 1, -1):
            candidate = dp[c - wi] + vi
            if candidate > dp[c]:
                dp[c] = candidate
                choice[i][c] = 1

    best = dp[capacity]

