def eulerian_trail(edges):
    m = len(edges)
    if m == 0:
        return []

    adj = {}
    indeg = {}
    outdeg = {}

    def ensure(u):
        if u not in adj:
            adj[u] = []
            indeg[u] = 0
            outdeg[u] = 0

    for idx, (u, v) in enumerate(edges):
        ensure(u)
        ensure(v)
        adj[u].append((v, idx))
        outdeg[u] += 1
        indeg[v] += 1

    start_candidates = [u for u in adj if outdeg[u] - indeg[u] == 1]
    end_candidates = [u for u in adj if indeg[u] - outdeg[u] == 1]
    if len(start_candidates) > 1 or len(end_candidates) > 1:
        return []
    if start_candidates and end_candidates:
        if start_candidates[0] == end_candidates[0]:
            return []
    if any(outdeg[u] != indeg[u] for u in adj
           if u not in start_candidates and u not in end_candidates):
        return []

    if start_candidates:
        start = start_candidates[0]
    else:
        start = next(u for u in adj if outdeg[u] > 0)

    # Connectivity check: all edges must be reachable from start in the
    # underlying undirected graph (nodes with no incident edges don't exist here).
    seen = {start}
    und = {}
    for u, v in edges:
        und.setdefault(u, []).append(v)
        und.setdefault(v, []).append(u)
    stack = [start]
    while stack:
        u = stack.pop()
        for w in und.get(u, ()):
            if w not in seen:
                seen.add(w)
                stack.append(w)
    if any(u not in seen for u in adj):
        return []

    pos = {u: 0 for u in adj}
    used = [False] * m
    trail = []
    stack = [(start, -1)]
    while stack:
        u, _ = stack[-1]
        advanced = False
        while pos[u] < len(adj[u]):
            v, eid = adj[u][pos[u]]
            pos[u] += 1
            if not used[eid]:
                used[eid] = True
                stack.append((v, eid))
                advanced = True
                break
        if not advanced:
            stack.pop()
            trail.append(u)

    if len(trail) != m + 1:
        return []
    trail.reverse()
    return trail
