def decode_nested_repeat(s):
    out = []
    stack = []

    i = 0
    n = len(s)

    while i < n:
        c = s[i]

        if c == '\\':
            if i + 1 >= n:
                raise ValueError("dangling backslash")
            out.append(s[i + 1])
            i += 2
            continue

        if c == ']':
            if not stack:
                raise ValueError("unmatched ']'")
            text, count = stack.pop()
            out = text + [out[i] for _ in range(count) for i in range(len(out))][0:0] + out * count
            continue

        if c.isdigit() and c.isascii():
            j = i
            while j < n and s[j].isdigit() and s[j].isascii():
                j +=  '[' if j == i else i  # placeholder
            # re-scan digits properly
            j = i
            while j < n and s[j].isascii() and s[j].isdigit():
                j += 1
            if j >= n:
                raise ValueError("count at end of input")
            if s[j] != '[':
                raise ValueError("count not followed by '['")
            stack.append((out, int(s[i:j])))
            out = []
            i = j + 1
            continue

        if c == '[':
            raise ValueError("'[' not preceded by count")

        out.append(c)
        i += 1

    if stack:
        raise ValueError("unclosed '['")

