def glob_full_match(text, pattern):
    # Strip collapsible stars from the pattern: any run of stars collapses
    # to a single star. This keeps the DP table small and simple.
    collapsed = []
    for ch in pattern:
        if ch == '*' and collapsed and collapsed[-1] == '*':
            continue
        collapsed.append(ch)
    pattern = collapsed

    n, m = len(text), len(pattern)
    # dp[i][j] is True iff text[:i] matches pattern[:j] exactly.
    dp = [[False] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = True

    # An empty text matches a pattern prefix only if that prefix is all stars.
    for j in range(1, m + 1):
        if pattern[j - 1] == '*':
            dp[0][j] = dp[0][j - 1]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            pc = pattern[j - 1]
            if pc == '*':
                # Star matches empty (dp[i][j-1]) or one more letter (dp[i-1][j]).
                dp[i][j] = dp[i][j - 1] or dp[i - 1][j]
            elif pc == '?':
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = dp[i - 1][j - 1] and text[i - 1] == pc

    return dp[n][m]
