def glob_full_match(text, pattern):
    n, m = len(text), len(pattern)

    # Strip trailing stars: they can only match the empty remainder.
    while m > 0 and pattern[m - 1] == '*':
        m -= 1

    # Dynamic programming over prefixes of text and pattern.
    # dp[j] == True means text[:i] matches pattern[:j].
    dp = [False] * (m + 1)
    dp[0] = True

    for j in range(1, m + 1):
        if pattern[j - 1] == '*':
            dp[j] = dp[j - 1]
        else:
            break

    for i in range(1, n + 1):
        prev = dp[0]
        dp[0] = False
        for j in range(1, m + 1):
            cur = dp[j]
            if pattern[j - 1] == '*':
                # Star matches empty (dp[j] from previous row)
                # or extends a match (dp[j - 1] in current row).
                dp[j] = dp[j] or dp[j - 1]
            else:
                dp[j] = prev and (pattern[j - 1] == '?' or pattern[j - 1] == text[i - 1])
            prev = cur

    return dp[m]
