def max_product_slice(nums):
    """
    Return (product, start, end) for the nonempty contiguous slice of `nums`
    with the largest product. `start` is inclusive, `end` exclusive, zero-based.
    Ties on product: prefer the shortest slice, then the smallest start index.
    Return None for an empty list.

    Single O(n) scan, O(1) auxiliary storage; the input is not modified.
    """
    n = len(nums)
    if n == 0:
        return None

    def better(cand, best):
        # True if candidate (prod, start, end) beats best under the tie rules.
        if best is None:
            return True
        if cand[0] != best[0]:
            return cand[0] > best[0]
        cand_len = cand[2] - cand[1]
        best_len = best[2] - best[1]
        if cand_len != best_len:
            return cand_len < best_len
        return cand[1] < best[1]

    best = None                      # (product, start, end) overall winner
    # Running states for the best slice ending at the current index:
    pos = neg = None                 # (product, start) with positive / negative product
    for i, x in enumerate(nums):
        # Candidate slices ending at i: extend each running state, or start fresh.
        cand_pos = None              # best positive-product slice ending at i
        cand_neg = None              # best negative-product slice ending at i

        fresh = (x, i)               # slice consisting of just nums[i]

        if pos is not None:
            p = pos[0] * x
            entry = (p, pos[1])
            if p > 0:
                cand_pos = entry
            elif p < 0:
                cand_neg = entry
            else:                    # product zeroed out; only the fresh slice matters
                pass

        if neg is not None:
            p = neg[0] * x
            entry = (p, neg[1])
            if p > 0:
                if cand_pos is None or better((p, neg[1], i + 1),
                                              (cand_pos[0], cand_pos[1], i + 1)):
                    cand_pos = entry
            elif p < 0:
                if cand_neg is None or better((p, neg[1], i + 1),
                                              (cand_neg[0], cand_neg[1], i + 1)):
                    cand_neg = entry

        # Fresh single-element slice always available.
        if x > 0:
            if cand_pos is None or better((x, i, i + 1),
                                          (cand_pos[0], cand_pos[1], i + 1)):
                cand_pos = fresh
        elif x < 0:
            if cand_neg is None or better((x, i, i + 1),
                                          (cand_neg[0], cand_neg[1], i + 1)):
                cand_neg = fresh
        # x == 0: contributes only the zero-product slice; handled via best below.

        pos, neg = cand_pos, cand_neg

        # Consider the best slice ending at i as a global candidate.
        if pos is not None:
            cand = (pos[0], pos[1], i + 1)
            if better(cand, best):
                best = cand
        if neg is not None:
            cand = (neg[0], neg[1], i + 1)
            if better(cand, best):
                best = cand
        if nums[i] == 0:
            cand = (0, i, i + 1)
            if better(cand, best):
                best = cand

    return best
