def largest_ones_square(grid):
    if not grid:
        return (0, -1, -1)
    width = len(grid[0])
    for row in grid:
        if len(row) != width:
            raise ValueError("row lengths differ")
    if width == 0:
        return (0, -1, -1)

    heights = [0] * width
    best_side = 0
    best_top = -1
    best_left = -1

    for top, row in enumerate(grid):
        for c in range(width):
            if row[c] == 1:
                heights[c] += 1
            else:
                heights[c] = 0
        stack = []
        i = 0
        while i <= width:
            h = heights[i] if i < width else 0
            start = i
            while stack and stack[-1][1] >= h:
                start, hh = stack.pop()
                if hh > 0:
                    side = min(hh, i - start)
                    if side > best_side:
                        best_side = side
                        best_top = top - side + 1
                        best_left = start
                    elif side == best_side and best_side > 0:
                        cand_top = top - side + 1
                        if cand_top < best_top or (cand_top == best_top and start < best_left):
                            best_top = cand_top
                            best_left = start
            if h > 0:
                stack.append((start, h))
            i += 1

    if best_side == 0:
        return (0, -1, -1)
    return (best_side, best_top, best_left)
