def largest_ones_square(grid):
    if not grid:
        return (0, -1, -1)

    width = len(grid[0])
    for row in grid:
        if len(row) != width:
            raise ValueError("row lengths differ")

    if width == 0:
        return (0, -1, -1)

    rows = len(grid)
    best_side = 0
    best_top = -1
    best_left = -1

    # heights[j] = number of consecutive 1s ending at current row in column j
    heights = [0] * width

    for i in range(rows):
        row = grid[i]
        for j in range(width):
            if row[j] == 1:
                heights[j] += 1
            else:
                heights[j] = 0

        # For each row, find the largest square whose bottom edge is on row i.
        # Use a monotonic stack over heights to get, for each j, the range of
        # columns where heights[j] is the limiting (minimal) height, then the
        # largest square side is min(height, run_length).
        stack = []  # indices with increasing heights
        j = 0
        while j <= width:
            h = heights[j] if j < width else 0
            while stack and heights[stack[-1]] >= h:
                top_idx = stack.pop()
                h_top = heights[top_idx]
                left_bound = stack[-1] + 1 if stack else 0
                right_bound = j - 1
                run = right_bound - left_bound + 1
                side = min(h_top, run)
                if side > best_side:
                    best_side = side
                    best_top = i - side + 1
                    best_left = left_bound
                elif side == best_side and side > 0:
                    cand_top = i - side + 1
                    cand_left = left_bound
                    if cand_top < best_top or (cand_top == best_top and cand_left < best_left):
                        best_top = cand_top
                        best_left = cand_left
                # Note: a square of side s needs height >= s over a run of >= s.
                # The maximal square using height h_top as the limiting height
                # over this run is min(h_top, run). But to catch all squares
                # (e.g., a square not limited by h_top but spanning this run),
                # we rely on the fact that for any maximal all-ones square,
                # its bottom row's limiting column is popped at some point.
                if stack and heights[stack[-1]] == h:
                    # merge equal heights to keep the widest run for tie-breaking
                    pass
            stack.append(j)
            j += 1

    if best_side == 0:
        return (0, -1, -1)
    return (best_side, best_top, best_left)
