def largest_ones_square(grid):
    """Find the largest axis-aligned square containing only 1s in a grid.

    Args:
        grid: list of rows (lists) containing only integers 0 and 1.

    Returns:
        (side, top, left): side length of the largest all-ones square and
        the zero-based top-left coordinates of its topmost-then-leftmost
        occurrence. Returns (0, -1, -1) if the grid contains no 1s.

    Raises:
        ValueError: if rows have differing lengths.
    """
    if not grid:
        return (0, -1, -1)

    width = len(grid[0])
    for row in grid:
        if len(row) != width:
            raise ValueError("rows must all have the same length")

    best_side = 0
    best_top = -1
    best_left = -1

    # Rolling DP row: dp[j] = side of largest all-ones square with
    # bottom-right corner at (current row, j).
    dp = [0] * width
    for i, row in enumerate(grid):
        prev_diag = 0  # dp[i-1][j-1]
        for j in range(width):
            temp = dp[j]  # dp[i-1][j], saved before overwrite
            if row[j] == 1:
                if i == 0 or j == 0:
                    dp[j] = 1
                else:
                    dp[j] = min(dp[j], dp[j - 1], prev_diag) + 1
                if dp[j] > best_side:
                    best_side = dp[j]
                    best_top = i - dp[j] + 1
                    best_left = j - dp[j] + 1
            else:
                dp[j] = 0
            prev_diag = temp

    if best_side == 0:
        return (0, -1, -1)
    return (best_side, best_top, best_left)
