def next_greater_steps(nums):
    n = len(nums)
    if n == 0:
        return []
    if n == 1:
        return [0]

    result = [0] * n
    # Stack holds indices whose next greater element has not been found yet.
    # We traverse the circular array twice; stack indices are kept in [0, n).
    stack = []

    for idx in range(2 * n):
        i = idx % n
        while stack and nums[stack[-1]] < nums[i]:
            j = stack.pop()
            result[j] = idx - j
        if idx < n:
            stack.append(i)

    return result

