def repeating_decimal(numerator, denominator):
    if denominator == 0:
        raise ZeroDivisionError("division by zero")
    if numerator == 0:
        return "0"

    sign = "-" if (numerator < 0) != (denominator < 0) else ""
    n = abs(numerator)
    d = abs(denominator)

    integer_part = n // d
    remainder = n % d

    if remainder == 0:
        return sign + str(integer_part)

    digits = []
    remainders = {}
    index = 0
    repeat_start = None

    while remainder != 0:
        if remainder in remainders:
            repeat_start = remainders[remainder]
            break
        remainders[remainder] = index
        remainder *= 10
        digits.append(str(remainder // d))
        remainder %= d
        index += 1

    if repeat_start is None:
        return sign + str(integer_part) + "." + "".join(digits)
    else:
        non_repeating = "".join(digits[:repeat_start])
        repeating = "".join(digits[repeat_start:])
        return (sign + str(integer_part) + "." + non_repeating +
                "(" + repeating + ")")
