from collections import defaultdict

def directed_euler_walk(n, edges):
    m = len(edges)
    if m == 0:
        return [0] if n > 0 else []
    deg_out = [0] * n
    deg_in = [0] * n
    for u, v in edges:
        deg_out[u] += 1
        deg_in[v] += 1
    # Choose start: vertex with out-in==1, else any vertex with edges, else 0.
    start = None
    for u in range(n):
        if deg_out[u] - deg_in[u] == 1:
            start = u
            break
    if start is None:
        start = 0
        for u in range(n):
            if deg_out[u] > 0:
                start = u
                break
    # Feasibility: exactly 0 or 1 vertices with out-in==1, exactly 0 or 1 with
    # in-out==1 (and they must match), all others balanced, and the edges must
    # be weakly connected (over vertices with degree > 0).
    plus = [u for u in range(n) if deg_out[u] - deg_in[u] == 1]
    minus = [u for u in range(n) if deg_in[u] - deg_out[u] == 1]
    if len(plus) > 1 or len(minus) > 1:
        return None
    if len(plus) != len(minus):
        return None
    # Weak connectivity check over vertices with edges (union-find).
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    for u, v in edges:
        union(u, v)
    root = None
    for u in range(n):
        if deg_out[u] + deg_in[u] > 0:
            r = find(u)
            if root is None:
                root = r
            elif r != root:
                return None
    # Hierholzer's algorithm using edge indices; each occurrence used once.
    # adj[u] holds (v, edge_index) pairs; we consume from the end and mark used.
    adj = [[] for _ in range(n)]
    for i, (u, v) in enumerate(edges):
        adj[u].append(i)
    used = [False] * m
    it = [0] * n  # pointer into adj[u] for consuming unused edges
    stack = [start]
    path = []
    while stack:
        u = stack[-1]
        # skip used edges
        while it[u] < len(adj[u]) and used[adj[u][it[u]]]:
            it[u] += 1
        if it[u] < len(adj[u]):
            ei = adj[u][it[u]]
            it[u] += 1
            used[ei] = True
            stack.append(edges[ei][1])
        else:
            path.append(stack.pop())
    if len(path) - 1 != m:
        return None
    path.reverse()
    return path

