def directed_euler_walk(n, edges):
    if not edges:
        return [0] if n > 0 else []

    from collections import defaultdict, Counter

    out_deg = Counter()
    in_deg = Counter()
    for u, v in edges:
        out_deg[u] += 1
        in_deg[v] += 1

    # Check Eulerian path condition: at most one vertex with out-in==1,
    # at most one with in-out==1, and all others balanced.
    extra_out = [v for v in out_deg if out_deg[v] - in_deg[v] == 1]
    extra_in = [v for v in in_deg if in_deg[v] - out_deg[v] == 1]
    if len(extra_out) > 1 or len(extra_in) > 1:
        return None
    if len(extra_out) != len(extra_in):
        return None
    for v in set(list(out_deg) + list(in_deg)):
        d = out_deg[v] - in_deg[v]
        if d != 0 and d != 1 and d != -1:
            return None

    # All vertices with edges must be in one connected component (weak connectivity
    # over vertices touched by edges). Use union-find.
    parent = {}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    for u, v in edges:
        for x in (u, v):
            if x not in parent:
                parent[x] = x
        union(u, v)

    roots = {find(x) for x in parent}
    if len(roots) > 1:
        return None

    # Choose start: the vertex with out = in + 1 if it exists, else any vertex
    # with an outgoing edge (or any vertex touched by an edge).
    if extra_out:
        start = extra_out[0]
    else:
        start = next(iter(out_deg))

    # Build adjacency: list of (neighbor, edge_index) per vertex, plus used flags.
    adj = defaultdict(list)
    for i, (u, v) in enumerate(edges):
        adj[u].append((v, i))
    used = [False] * len(edges)
    ptr = defaultdict(int)

    # Iterative Hierholzer's algorithm producing a walk (path, not closed cycle
    # requirement — we just need a continuous trail using every edge once).
    # Standard approach: build the postorder of edges via stack, then reverse.
    stack = [start]
    edge_postorder = []
    while stack:
        u = stack[-1]
        # advance pointer past used edges
        while ptr[u] < len(adj[u]) and used[adj[u][ptr[u]][1]]:
            ptr[u] += 1
        if ptr[u] < len(adj[u]):
            v, idx = adj[u][ptr[u]]
            used[idx] = True
            ptr[u] += 1
            stack.append(v)
        else:
            stack.pop()
            if stack:
                edge_postorder.append(u)

    # edge_postorder has len(edges) entries if all edges were consumed.
    if len(edge_postorder) != len(edges):
        return None

    # Reconstruct vertex walk: walk = [start reversed-postorder ... ] 
    # The classic reconstruction: reverse the postorder of vertices visited
    # when retreating; the walk is start + reversed(edge_postorder).
    walk = [start] + edge_postorder[::-1]
    return walk
