import heapq


def deadline_dispatch(events):
    results = []
    pending = {}   # task -> (deadline, seq, task) for its latest 'set'
    seq = 0        # monotonically increasing 'set' counter for tie-breaking

    for event in events:
        if not isinstance(event, tuple) and not isinstance(event, list):
            raise ValueError("event must be a tuple")

        if len(event) == 0:
            raise ValueError("empty event tuple")

        op = event[0]
        if not isinstance(op, str):
            raise ValueError("operation must be a string")

        if op == 'set':
            if len(event) != 3:
                raise ValueError("'set' expects 2 arguments")
            task, deadline = event[1], event[2]
            if not isinstance(task, str) or not task.isascii() or not task.islower() or not task:
                raise ValueError("invalid task id")
            if isinstance(deadline, bool) or not isinstance(deadline, int):
                raise ValueError("deadline must be an integer")
            if deadline < 0:
                raise ValueError("deadline must be nonnegative")
            seq += 1
            entry = (deadline, seq, task)
            pending[task] = entry

        elif op == 'cancel':
            if len(event) != 2:
                raise ValueError("'cancel' expects 1 argument")
            task = event[1]
            if not isinstance(task, str) or not task.isascii() or not task.islower() or not task:
                raise ValueError("invalid task id")
            if task in pending:
                del pending[task]

        elif op == 'run':
            if len(event) != 2:
                raise ValueError("'run' expects 1 argument")
            threshold = event[1]
            if isinstance(threshold, bool) or not isinstance(threshold, int):
                raise ValueError("threshold must be an integer")
            if threshold < 0:
                raise ValueError("threshold must be nonnegative")

            # Collect currently pending tasks with deadline <= threshold.
            due = [entry for entry in pending.values() if entry[0] <= threshold]
            heapq.heapify(due)

            executed = []
            while due:
                deadline, _, task = heapq.heappop(due)
                executed.append(task)
                del pending[task]

            results.append(executed)

        else:
            raise ValueError("unknown operation")

    return results
