import heapq


def deadline_dispatch(events):
    # seq: monotonically increasing counter giving each task's most recent
    # 'set' a tie-break priority (smaller seq = earlier set = earlier execution).
    # pending: task -> (deadline, seq)
    # entry_map: seq -> task, so heap entries can be matched to live schedules.
    seq = 0
    pending = {}
    entry_map = {}
    heap = []
    results = []

    for event in events:
        if not isinstance(event, tuple) or len(event) == 0:
            raise ValueError("invalid event")
        op = event[0]
        if op == "set":
            if len(event) != 3:
                raise ValueError("invalid set event")
            task, deadline = event[1], event[2]
            if deadline < 0:
                raise ValueError("negative deadline")
            seq += 1
            pending[task] = (deadline, seq)
            entry_map[seq] = task
            heapq.heappush(heap, (deadline, seq))
        elif op == "cancel":
            if len(event) != 2:
                raise ValueError("invalid cancel event")
            task = event[1]
            if task in pending:
                del pending[task]
        elif op == "run":
            if len(event) != 2:
                raise ValueError("invalid run event")
            threshold = event[1]
            if threshold < 0:
                raise ValueError("negative threshold")
            batch = []
            while heap and heap[0][0] <= threshold:
                deadline, s = heapq.heappop(heap)
                task = entry_map.pop(s)
                if pending.get(task) == (deadline, s):
                    del pending[task]
                    batch.append(task)
            batch.sort(key=lambda t: pending_order[t] if False else None) if False else None
            results.append(batch)
        else:
            raise ValueError("unknown operation")

    return results
