def expand_counted_pattern(s):
    def parse(i):
        parts = []
        while i < len(s):
            c = s[i]
            if c == '\\':
                if i + 1 >= len(s):
                    raise ValueError("trailing backslash")
                parts.append(s[i + 1])
                i += 2
            elif c == '[':
                raise ValueError("bare '['")
            elif c == ']':
                return ''.join(parts), i
            elif c.isdigit():
                j = i
                while j < len(s) and s[j].isdigit():
                    j += 1
                if j >= len(s) or s[j] != '[':
                    raise ValueError("digit run not followed by '['")
                count = int(s[i:j])
                inner, i = parse(j + 1)
                if i >= len(s) or s[i] != ']':
                    raise ValueError("unmatched bracket")
                parts.append(inner * count)
                i += 1
            else:
                parts.append(c)
                i += 1
        return ''.join(parts), i

    result, i = parse(0)
    if i < len(s):
        raise ValueError("unmatched bracket")
    return result
