def expand_counted_pattern(s):
    pos = 0
    n = len(s)

    def parse(stop_bracket):
        nonlocal pos
        parts = []
        while pos < n:
            c = s[pos]
            if c == '\\':
                if pos + 1 >= n:
                    raise ValueError("trailing backslash")
                parts.append(s[pos + 1])
                pos += 2
            elif c == '[':
                raise ValueError("bare '['")
            elif c == ']':
                if stop_bracket:
                    pos += 1
                    return ''.join(parts)
                raise ValueError("unmatched ']'")
            elif c.isdigit():
                start = pos
                while pos < n and s[pos].isdigit():
                    pos += 1
                if pos >= n or s[pos] != '[':
                    raise ValueError("digit run not followed by '['")
                count = int(s[start:pos])
                pos += 1
                seq = parse(True)
                parts.append(seq * count)
            else:
                parts.append(c)
                pos += 1
        if stop_bracket:
            raise ValueError("unmatched '['")
        return ''.join(parts)

    return parse(False)
