def min_capacity_for_days(weights, days):
    def can_ship(capacity):
        used_days = 1
        current = 0
        for w in weights:
            if current + w > capacity:
                used_days += 1
                current = w
                if used_days > days:
                    return False
            else:
                current += w
        return True

    lo = max(weights)
    hi = sum(weights)
    while lo < hi:
        mid = (lo + hi) // 2
        if can_ship(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo
