def smallest_fixed_digit_sum(d, s):
    if d < 1:
        raise ValueError("d must be at least 1")
    if s < 0:
        raise ValueError("s must be nonnegative")
    if d == 1:
        return s if s <= 9 else -1
    if s < 1 or s > 9 * d:
        return -1
    digits = [0] * d
    remaining = s
    # Fill from the least significant position, using the largest digit that
    # still leaves at least 1 for the leading digit (positions 2..d).
    for i in range(d, 1, -1):
        digit = min(9, remaining - 1)
        digits[i - 1] = digit
        remaining -= digit
    digits[0] = remaining
    return int(''.join(map(str, digits)))
