def assignment_min_cost_bitmask(cost):
    n = len(cost)
    if n == 0:
        return 0
    full = (1 << n) - 1
    INF = float('inf')
    dp = [INF] * (1 << n)
    dp[0] = 0
    for mask in range(1 << n):
        cur = dp[mask]
        if cur == INF:
            continue
        # number of rows already assigned = popcount(mask)
        # next row to assign is that index
        row = bin(mask).count('1')
        if row >= n:
            continue
        for col in range(n):
            if not (mask >> col) & 1:
                new_mask = mask | (1 << col)
                val = cur + cost[row][col]
                if val < dp[new_mask]:
                    dp[new_mask] = val
    return dp[full]
