    rows, cols = len(grid), len(grid[0])
    start = target = None
    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if ch == 'S':
                start = (r, c)
            elif ch == 'T':
                target = (r, c)
    if start is None or target is None:
        return -1

    full_mask = 0
    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if ch in ('a', 'b', 'c'):
                full_mask |= 1 << (ord(ch) - ord('a'))

    start_state = (start[0], start[1], 0)
    dist = {start_state: 0}
    queue = deque([start_state])

    while queue:
        r, c, keys = queue.popleft()
        d = dist[(r, c, keys)]
        if (r, c) == target:
            return d
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if not (0 <= nr < rows and 0 <= nc < cols):
                continue
            ch = grid[nr][nc]
            if ch == '#':
                continue
            if ch in ('A', 'B', 'C'):
                bit = 1 << (ord(ch) - ord('A'))
                if not (keys & bit):
                    continue
                nkeys = keys
            elif ch in ('a', 'b', 'c'):
                nkeys = keys | (1 << (ord(ch) - ord('a')))
            else:
                nkeys = keys
            state = (nr, nc, nkeys)
            if state not in dist:
                dist[state] = d + 1
                queue.append(state)

    return -1
