    dp = {s: 1 for s in states}

    for _ in range(cols - 1):
        ndp = dict.fromkeys(states, 0)
        for a in states:
            va = dp[a]
            if va:
                for b in compat[a]:
                    ndp[b] = (ndp[b] + va) % MOD
        dp = ndp

    return sum(dp.values()) % MOD

