def count_grid_independent_sets(rows, cols):
    MOD = 1000000007
    if rows <= 0 or cols <= 0:
        return 1
    c = cols
    full = 1 << c
    # Horizontally valid masks for one row
    valid = [m for m in range(full) if (m & (m >> 1)) == 0]
    # Compatibility lists: for each valid mask b, all valid masks a with a & b == 0
    compat = {b: [a for a in valid if (a & b) == 0] for b in valid}
    # dp over masks of the current row
    dp = {b: 1 for b in valid}
    for _ in range(rows - 1):
        ndp = {}
        for b in valid:
            s = 0
            for a in compat[b]:
                s += dp[a]
            ndp[b] = s % MOD
        dp = ndp
    return sum(dp.values()) % MOD
