def first_winning_subtraction_move(stones, moves):
    winning = [False] * (stones + 1)
    for n in range(1, stones + 1):
        winning[n] = any(m <= n and not winning[n - m] for m in moves)
    for m in sorted(moves):
        if m <= stones and not winning[stones - m]:
            return m
    return -1
