def repeating_positional_cycle_length(numerator, denominator, base):
    d = denominator
    while d % 2 == 0:
        d //= 2
    while d % 5 == 0:
        d //= 5
    if d == 1:
        return 0
    n = numerator % d
    if n == 0:
        return 0
    # Remove factors of base from d as well (they behave like terminating factors).
    while d % base == 0:
        d //= base
    n %= d
    if n == 0:
        return 0
    k = 1
    r = n % base
    while r != 1:
        r = (r * base) % d
        k += 1
        if k > d:
            return 0
    return k

