def repeating_positional_cycle_length(numerator, denominator, base):
    from math import gcd

    n = numerator
    d = denominator

    # Fully reduce the fraction.
    g = gcd(n, d)
    if g:
        n //= g
        d //= g
    if n == 0:
        return 0

    # Find prime factors of the base.
    primes = []
    m = base
    f = 2
    while f * f <= m:
        if m % f == 0:
            primes.append(f)
            while m % f == 0:
                m //= f
        f += 1
    if m > 1:
        primes.append(m)

    # Strip terminating prime factors from d.
    for p in primes:
        while d % p == 0:
            d //= p

    if d == 1:
        return 0

    # Cycle length = multiplicative order of base modulo d.
    r = base % d
    k = 1
    while r != 1:
        r = (r * base) % d
        k += 1
        if k > d:
            return 0
    return k

